{
  "vision": "Empower treasury operations with a unified payment administration workspace that simplifies merchant and batch management, accelerates approvals, ensures audit integrity, and integrates seamlessly with PaymentCore and Payment Rail systems to handle cross-rail payouts efficiently.",
  "scope": "Deliver a Next.js + TypeScript UI connected to PaymentCore GraphQL and Payment Rail REST APIs through API Gateway. Enable search, drill-down, refunds, approvals, and anomaly alerts for treasury operations. Include audit logging to Kafka/S3 and enforce RBAC. Exclude non-core financial operations or external network integrations.",
  "success_criteria": [
    "Search and payout workflows execute under defined performance thresholds (<1.5s for queries, <4s for payouts)",
    "Audit logs are generated for all payment actions and verified in Kafka/S3",
    "RBAC correctly restricts approval and refund actions based on roles (OpsAnalyst, Manager, Auditor)"
  ],
  "user_stories": [
    {
      "id": "US-001",
      "title": "Enable treasury analyst to search merchants and payment batches across ACH, RTP, and wire rails",
      "as_a": "OpsAnalyst",
      "i_want": "to search and filter merchants and payment batches efficiently across multiple payment rails",
      "so_that": "I can quickly identify transactions and exceptions without manual reconciliation",
      "acceptance_criteria": [
        {"given": "a logged-in OpsAnalyst with proper RBAC access", "when": "they enter search filters for a merchant or batch", "then": "the system displays results within 1.5 seconds from read-only replicas"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["search", "performance", "payment-admin"]
    },
    {
      "id": "US-002",
      "title": "Display detailed settlement timeline and payment transaction drill-down view",
      "as_a": "OpsAnalyst",
      "i_want": "to view timeline details for settlements and batch transactions",
      "so_that": "I can track the progress and status of each payment within a batch",
      "acceptance_criteria": [
        {"given": "a payment batch is selected", "when": "the analyst drills into the settlement timeline", "then": "the system retrieves ledger and rail event data from PaymentCore GraphQL within 1.5 seconds"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["drilldown", "ledger", "timeline"]
    },
    {
      "id": "US-003",
      "title": "Allow refund or adjustment initiation for an eligible transaction",
      "as_a": "OpsAnalyst",
      "i_want": "to trigger refunds or adjustments on qualifying payments",
      "so_that": "I can resolve exceptions directly from the admin workspace",
      "acceptance_criteria": [
        {"given": "a transaction marked eligible for refund", "when": "the analyst initiates an adjustment", "then": "an API call is made through Payment Actions service to Payment Rail REST endpoint and audit logs are emitted to Kafka and S3"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["refunds", "adjustments", "audit"]
    },
    {
      "id": "US-004",
      "title": "Enable manager approval of payout batches using automated allocation rules",
      "as_a": "Manager",
      "i_want": "to review and approve payout batches with predefined allocation logic",
      "so_that": "I can ensure accuracy and compliance for high-volume daily disbursements",
      "acceptance_criteria": [
        {"given": "a payout batch pending approval", "when": "the manager submits approval", "then": "the system applies automated allocation rules, triggers PaymentCore mutation via Payment Actions service, and logs the event to audit.payments"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["approval", "automation", "rbac"]
    },
    {
      "id": "US-005",
      "title": "Surface payment anomaly alerts in the admin workspace dashboard",
      "as_a": "OpsAnalyst",
      "i_want": "to see anomaly alerts related to settlement discrepancies",
      "so_that": "I can act early on irregular payment behaviors",
      "acceptance_criteria": [
        {"given": "Payment Rail event streams detect anomalies", "when": "the workspace dashboard refreshes", "then": "alerts are displayed with relevant merchant and batch context"}
      ],
      "priority": "Medium",
      "story_points": 5,
      "labels": ["alerts", "anomalies", "dashboard"]
    },
    {
      "id": "US-006",
      "title": "Provide export functionality for audit-ready payment reports",
      "as_a": "Auditor",
      "i_want": "to export comprehensive reports of transactions and approvals",
      "so_that": "I can perform audits without manual data extraction",
      "acceptance_criteria": [
        {"given": "an auditor with RBAC access", "when": "they trigger export for a selected timeframe", "then": "the system generates an audit-ready CSV or JSON and archives it to S3"}
      ],
      "priority": "Medium",
      "story_points": 3,
      "labels": ["audit", "export", "reporting"]
    }
  ]
}

{
  "architecture_overview": "A modular payment administration workspace built on Next.js 14 (TypeScript) consuming backend APIs through a secured Node.js gateway service. The frontend provides search, drill-down, refund, approval, anomaly alert, and report export functionality. Backend services integrate with PaymentCore GraphQL for ledger data and Payment Rail REST APIs for disbursement actions, orchestrated through the Payment Actions service. Audit events are emitted to Kafka (audit.payments topic) and archived to S3. The system runs inside a private VNet with enforced RBAC and mTLS/OAuth2-secured communication.",
  "technology_stack": [
    "Next.js 14",
    "TypeScript",
    "Node.js",
    "GraphQL",
    "REST",
    "Kafka",
    "AWS S3",
    "OAuth2",
    "mTLS",
    "shadcn/ui"
  ],
  "api_endpoints": [
    {
      "method": "POST",
      "path": "/api/search",
      "description": "Search merchants and payment batches using PaymentCore GraphQL via API Gateway.",
      "request_body": {
        "merchantName": "string",
        "batchId": "string",
        "paymentRail": "enum('ACH','RTP','WIRE')",
        "dateRange": {
          "from": "ISODate",
          "to": "ISODate"
        },
        "page": "number",
        "pageSize": "number"
      },
      "response": {
        "results": [
          {
            "merchantId": "string",
            "merchantName": "string",
            "batchId": "string",
            "rail": "string",
            "status": "string",
            "totalAmount": "number"
          }
        ],
        "pagination": {
          "total": "number",
          "page": "number"
        }
      }
    },
    {
      "method": "GET",
      "path": "/api/batches/:batchId/timeline",
      "description": "Retrieve settlement timeline and transaction details from PaymentCore and Payment Rail APIs.",
      "request_body": null,
      "response": {
        "batchId": "string",
        "rail": "string",
        "timeline": [
          {
            "event": "string",
            "timestamp": "ISODate",
            "status": "string",
            "ledgerEntry": "string"
          }
        ]
      }
    },
    {
      "method": "POST",
      "path": "/api/payments/:paymentId/refund",
      "description": "Trigger refund or adjustment for eligible payment through Payment Actions to Payment Rail REST APIs and emit audit to Kafka/S3.",
      "request_body": {
        "paymentId": "string",
        "reason": "string",
        "amount": "number"
      },
      "response": {
        "refundId": "string",
        "status": "string"
      }
    },
    {
      "method": "POST",
      "path": "/api/payouts/:batchId/approve",
      "description": "Approve payout batch applying automated allocation rules and audit logging via Payment Actions service.",
      "request_body": {
        "batchId": "string",
        "managerId": "string",
        "allocationPolicy": "string"
      },
      "response": {
        "approvalId": "string",
        "status": "string",
        "allocatedAmount": "number"
      }
    },
    {
      "method": "GET",
      "path": "/api/alerts",
      "description": "Fetch anomaly alerts from Payment Rail event stream for display in workspace dashboard.",
      "request_body": null,
      "response": {
        "alerts": [
          {
            "alertId": "string",
            "type": "string",
            "batchId": "string",
            "merchantId": "string",
            "message": "string",
            "severity": "string",
            "timestamp": "ISODate"
          }
        ]
      }
    },
    {
      "method": "GET",
      "path": "/api/reports/export",
      "description": "Export audit-ready payment reports in CSV or JSON and archive to S3.",
      "request_body": {
        "from": "ISODate",
        "to": "ISODate",
        "format": "enum('csv','json')"
      },
      "response": {
        "downloadUrl": "string",
        "archivedTo": "string"
      }
    }
  ],
  "database_schema": "All queries are performed on read-only Postgres replicas via PaymentCore GraphQL. No schema changes required. Key tables accessible via GraphQL: merchants(id, name, region), payment_batches(id, rail, total_amount, status, approved_by), payments(id, batch_id, amount, status, ledger_entry), settlements(id, payment_id, timestamp, status). Write operations occur only through Payment Actions and Payment Rail APIs (outside direct DB access).",
  "security_considerations": [
    "mTLS enforced between all service-to-service communications inside private VNet",
    "OAuth2 client credentials for API Gateway authentication to PaymentCore and Payment Rail APIs",
    "RBAC roles (OpsAnalyst, Manager, Auditor) enforced at both frontend feature gating and backend authorization middleware",
    "Audit logging to Kafka and S3 with retry and message integrity validation",
    "Strict IAM for S3 audit buckets (write-only, encrypted at rest)",
    "No direct DB writes—mutations go through Payment Actions service with controlled transaction boundaries",
    "Ensure CSRF protection for UI forms and hardened input validation to prevent injection attacks",
    "Logs and PII masked per compliance standards during audit export"
  ],
  "code_structure": {
    "frontend": {
      "root": "apps/payment-admin-ui/",
      "structure": [
        "pages/ (route handlers and views)",
        "components/ (shadcn/ui-based modular components)",
        "hooks/ (GraphQL and REST API fetch hooks)",
        "contexts/ (RBAC user role context)",
        "utils/ (formatters, validators)",
        "styles/ (existing design tokens integration)"
      ]
    },
    "backend": {
      "root": "services/payment-admin-api/",
      "structure": [
        "src/controllers/ (business logic mapping to API endpoints)",
        "src/integrations/ (PaymentCore GraphQL and Payment Rail REST clients)",
        "src/middleware/ (RBAC enforcement, mTLS/OAuth2 handling)",
        "src/audit/ (Kafka and S3 emitters)",
        "src/config/ (env, private VNet setup)",
        "tests/ (Jest integration tests for refund/approval flows)"
      ]
    },
    "shared": {
      "package": "libs/shared-types/",
      "contents": [
        "GraphQL types and REST DTOs",
        "RBAC role enums",
        "Audit event interface definitions"
      ]
    }
  },
  "implementation_notes": "Use Next.js server components for secure API proxying to hide credentials. Implement caching for search query responses to maintain <1.5s SLA. Refunds and approvals trigger Payment Actions service asynchronously with audit event emission pipeline (Kafka producer + S3 archival worker). Utilize role-based guards at both UI and server levels for RBAC enforcement. Integration tests to simulate full refund and payout flows verifying Kafka topic messages and S3 artifacts. Configure CI/CD to deploy both frontend and backend inside private VNet with mTLS certificates provisioned via internal PKI. Maintain system observability with performance metrics logged into Grafana/Prometheus internal stack."
}

{
  "summary": "Implements a production-ready Node.js backend API with secure integrations to PaymentCore (GraphQL) and Payment Rail (REST), supporting search, drilldowns, refunds, approvals, alerts, and report exports with RBAC and audit logging via Kafka/S3 as defined in the Tech Lead's design.",
  "code_files": [
    {
      "filename": "services/payment-admin-api/src/controllers/searchController.js",
      "language": "javascript",
      "description": "Handles merchant and payment batch search using PaymentCore GraphQL API via API Gateway with caching and SLA compliance.",
      "code": "import express from 'express';
import PaymentCoreClient from '../integrations/paymentCoreClient.js';
import { authorizeRole } from '../middleware/rbac.js';
import cache from '../utils/cache.js';

const router = express.Router();

router.post('/search', authorizeRole(['OpsAnalyst','Manager','Auditor']), async (req, res) => {
  try {
    const { merchantName, batchId, paymentRail, dateRange, page, pageSize } = req.body;
    const cacheKey = JSON.stringify({ merchantName, batchId, paymentRail, dateRange, page, pageSize });
    const cached = cache.get(cacheKey);
    if (cached) return res.json(cached);

    const query = `query SearchBatches($merchantName:String,$batchId:String,$rail:String,$from:DateTime,$to:DateTime,$page:Int,$pageSize:Int){
      searchBatches(merchantName:$merchantName,batchId:$batchId,rail:$rail,from:$from,to:$to,page:$page,pageSize:$pageSize){
        results{ merchantId merchantName batchId rail status totalAmount }
        pagination{ total page }
      }
    }`;

    const data = await PaymentCoreClient.query(query, { merchantName, batchId, rail: paymentRail, from: dateRange.from, to: dateRange.to, page, pageSize });
    cache.set(cacheKey, data, 60);
    res.json(data.searchBatches);
  } catch (err) {
    console.error('Search error', err);
    res.status(500).json({ error: 'Failed to perform search' });
  }
});

export default router;"
    },
    {
      "filename": "services/payment-admin-api/src/controllers/paymentController.js",
      "language": "javascript",
      "description": "Manages refund or adjustment initiation through Payment Actions service and triggers audit logging to Kafka/S3.",
      "code": "import express from 'express';
import PaymentRailClient from '../integrations/paymentRailClient.js';
import { emitAuditEvent } from '../audit/auditEmitter.js';
import { authorizeRole } from '../middleware/rbac.js';

const router = express.Router();

router.post('/payments/:paymentId/refund', authorizeRole(['OpsAnalyst','Manager']), async (req, res) => {
  try {
    const { paymentId } = req.params;
    const { reason, amount } = req.body;
    const response = await PaymentRailClient.post(`/actions/refund`, { paymentId, reason, amount });
    await emitAuditEvent({ action: 'REFUND_INITIATED', paymentId, reason, amount, status: response.status });
    res.json({ refundId: response.data.refundId, status: response.status });
  } catch (err) {
    console.error('Refund failed', err);
    res.status(500).json({ error: 'Refund initiation failed' });
  }
});

export default router;"
    },
    {
      "filename": "services/payment-admin-api/src/controllers/payoutController.js",
      "language": "javascript",
      "description": "Handles payout batch approval applying automated allocation rules and auditing the event.",
      "code": "import express from 'express';
import PaymentActionsClient from '../integrations/paymentActionsClient.js';
import { emitAuditEvent } from '../audit/auditEmitter.js';
import { authorizeRole } from '../middleware/rbac.js';

const router = express.Router();

router.post('/payouts/:batchId/approve', authorizeRole(['Manager']), async (req, res) => {
  try {
    const { batchId } = req.params;
    const { managerId, allocationPolicy } = req.body;
    const approval = await PaymentActionsClient.post(`/batches/${batchId}/approve`, { managerId, allocationPolicy });
    await emitAuditEvent({ action: 'PAYOUT_APPROVAL', batchId, managerId, status: approval.status, allocatedAmount: approval.data.allocatedAmount });
    res.json({ approvalId: approval.data.approvalId, status: approval.status, allocatedAmount: approval.data.allocatedAmount });
  } catch (err) {
    console.error('Approval error', err);
    res.status(500).json({ error: 'Payout approval failed' });
  }
});

export default router;"
    },
    {
      "filename": "services/payment-admin-api/src/controllers/reportController.js",
      "language": "javascript",
      "description": "Exports audit-ready payment reports to S3 and returns download URLs to auditors.",
      "code": "import express from 'express';
import S3Client from '../integrations/s3Client.js';
import { authorizeRole } from '../middleware/rbac.js';
import { generateReportData } from '../utils/reportGenerator.js';
import { emitAuditEvent } from '../audit/auditEmitter.js';

const router = express.Router();

router.get('/reports/export', authorizeRole(['Auditor']), async (req, res) => {
  try {
    const { from, to, format } = req.query;
    const reportData = await generateReportData(from, to);
    const fileKey = `audit-reports/report-${Date.now()}.${format}`;
    await S3Client.upload(fileKey, reportData, format);
    await emitAuditEvent({ action: 'REPORT_EXPORTED', range: { from, to }, format, fileKey });
    res.json({ downloadUrl: S3Client.getSignedUrl(fileKey), archivedTo: fileKey });
  } catch (err) {
    console.error('Report export failed', err);
    res.status(500).json({ error: 'Failed to export report' });
  }
});

export default router;"
    },
    {
      "filename": "services/payment-admin-api/src/audit/auditEmitter.js",
      "language": "javascript",
      "description": "Emit audit events to Kafka topic and also archive payloads to S3 for SOX compliance.",
      "code": "import { Kafka } from 'kafkajs';
import S3Client from '../integrations/s3Client.js';

const kafka = new Kafka({ brokers: [process.env.KAFKA_BROKER], ssl:true });
const producer = kafka.producer();
await producer.connect();

export async function emitAuditEvent(event) {
  const payload = { ...event, timestamp: new Date().toISOString() };
  try {
    await producer.send({ topic:'audit.payments', messages:[{ value: JSON.stringify(payload) }] });
    await S3Client.upload(`audit-events/${event.action}-${Date.now()}.json`, JSON.stringify(payload), 'json');
  } catch (err) {
    console.error('Audit emission failed', err);
  }
}"
    },
    {
      "filename": "services/payment-admin-api/src/middleware/rbac.js",
      "language": "javascript",
      "description": "Middleware enforcing RBAC for OpsAnalyst, Manager, and Auditor roles.",
      "code": "export function authorizeRole(allowedRoles) {
  return (req, res, next) => {
    const userRole = req.headers['x-user-role'];
    if (!allowedRoles.includes(userRole)) {
      return res.status(403).json({ error: 'Access denied' });
    }
    next();
  };
}"
    }
  ],
  "setup_instructions": [
    "cd services/payment-admin-api",
    "npm install",
    "npm run build",
    "npm run dev"
  ],
  "environment_variables": [
    {
      "name": "DATABASE_URL",
      "description": "PaymentCore Postgres replica connection through GraphQL API Gateway",
      "example": "postgresql://user:pass@paymentcore-readonly:5432/core"
    },
    {
      "name": "KAFKA_BROKER",
      "description": "Broker endpoint inside private VNet for audit events",
      "example": "kafka.internal:9093"
    },
    {
      "name": "S3_BUCKET",
      "description": "AWS S3 bucket for audit archive storage (write-only, encrypted)",
      "example": "audit-payments-bucket"
    },
    {
      "name": "OAUTH_CLIENT_ID",
      "description": "OAuth2 client ID for API Gateway authentication",
      "example": "payment-admin-api-client"
    },
    {
      "name": "OAUTH_CLIENT_SECRET",
      "description": "OAuth2 client secret for API Gateway authentication",
      "example": "supersecret123"
    }
  ],
  "dependencies": [
    {
      "name": "express",
      "version": "^4.18.0",
      "purpose": "HTTP server framework for API endpoints"
    },
    {
      "name": "kafkajs",
      "version": "^2.2.4",
      "purpose": "Kafka client for audit event emissions"
    },
    {
      "name": "aws-sdk",
      "version": "^2.1475.0",
      "purpose": "Connect and upload audit payloads to S3 archives"
    },
    {
      "name": "node-cache",
      "version": "^5.1.2",
      "purpose": "Simple in-memory cache for search query results to improve performance"
    },
    {
      "name": "axios",
      "version": "^1.6.0",
      "purpose": "HTTP client for GraphQL and REST integration with PaymentCore and Payment Rail APIs"
    }
  ]
}
